import os
import re
import requests
import pandas as pd
from bs4 import BeautifulSoup
import urllib.parse


def get_coverage(char):
    """Extrae 3 métricas de Hanzicraft:
    - Appears in X words
    - Component in Y characters
    - Adds ~Z% reading coverage
    """
    url_base = "https://hanzicraft.com/character/"
    encoded = urllib.parse.quote(char, encoding='utf-8')
    url = url_base + encoded

    headers = {"User-Agent": "Mozilla/5.0"}
    resp = requests.get(url, headers=headers, timeout=20)
    resp.raise_for_status()

    soup = BeautifulSoup(resp.text, "html.parser")
    text = soup.get_text(" ", strip=True)

    # 1. Appears in X words
    appears_match = re.search(
        r"Appears in\s+(\d+)\s+words",
        text,
        re.IGNORECASE
    )

    # 2. Component in Y characters
    component_match = re.search(
        r"Component in\s+(\d+)\s+characters",
        text,
        re.IGNORECASE
    )

    # 3. Adds ~Z% to reading coverage
    coverage_match = re.search(
        r"Adds\s*~?\s*([0-9.]+%)\s*to your reading coverage",
        text,
        re.IGNORECASE
    )

    appears = appears_match.group(1) if appears_match else None
    component = component_match.group(1) if component_match else None
    coverage = coverage_match.group(1) if coverage_match else None

    return appears, component, coverage


